// Generated by x402-starter-kit. A small x402 seller (Express) for local practice. Testnet only. Not a real service.
// It listens on 127.0.0.1 only, so nothing outside your computer can reach it.
import fs from "node:fs";
import express from "express";
import { Keypair, StrKey } from "@stellar/stellar-sdk";
import { paymentMiddlewareFromConfig } from "@x402/express";
import { HTTPFacilitatorClient } from "@x402/core/server";
import { ExactStellarScheme } from "@x402/stellar/exact/server";

const projectFile = new URL("./project.json", import.meta.url);
const project = JSON.parse(fs.readFileSync(projectFile, "utf8"));
const { method, path: routePath, price } = project.variant;
if (!["GET", "POST"].includes(method) || !/^\/[a-z0-9/_-]+$/.test(routePath)) {
  throw new Error("project.json has an unsupported method or path.");
}

const PORT = Number(process.env.PORT || 4402);
const FACILITATOR_URL = process.env.FACILITATOR_URL || "https://www.x402.org/facilitator";
const NETWORK = "stellar:testnet";

// The payee is a public address only. It is created once and the secret key is discarded on purpose:
// nothing in this project can spend from it.
let payTo = process.env.PAY_TO || project.payee;
if (payTo && !StrKey.isValidEd25519PublicKey(payTo)) {
  throw new Error("PAY_TO is not a valid Stellar public address (G...).");
}
if (!payTo) {
  payTo = Keypair.random().publicKey();
  project.payee = payTo;
  fs.writeFileSync(projectFile, JSON.stringify(project, null, 2) + "\n");
}

const RESOURCE = {
    "title": "Quote of the day",
    "quote": "Small steps, taken daily, add up."
  };

const app = express();

// ---- response clean-up (added by the team) ----
const decode = (value) => JSON.parse(Buffer.from(value, "base64").toString("utf8"));
const encode = (value) => Buffer.from(JSON.stringify(value)).toString("base64");

// res is { status, headers, body }. Change it as needed and return it.
function cleanUp(res) {
  // Older clients read the challenge from the body, not from a header.
  const challenge = decode(res.headers["payment-required"]);
  res.body = JSON.stringify({
    x402Version: 1,
    error: "Payment required",
    accepts: challenge.accepts.map((a) => ({
      scheme: a.scheme,
      network: a.network,
      maxAmountRequired: a.amount,
      resource: challenge.resource?.url ?? "",
      description: challenge.resource?.description || "Paid resource",
      mimeType: "application/json",
      payTo: a.payTo,
      maxTimeoutSeconds: a.maxTimeoutSeconds,
      asset: a.asset,
    })),
  });
  delete res.headers["payment-required"];
  return res;
}

app.use((req, res, next) => {
  const end = res.end.bind(res);
  res.end = (chunk, ...rest) => {
    if (res.statusCode !== 402) return end(chunk, ...rest);
    const out = cleanUp({
      status: res.statusCode,
      headers: { "payment-required": res.getHeader("payment-required") },
      body: chunk ? chunk.toString() : "",
    });
    res.statusCode = out.status;
    const header = out.headers["payment-required"];
    if (header === undefined) res.removeHeader("payment-required");
    else res.setHeader("payment-required", header);
    res.setHeader("content-length", Buffer.byteLength(out.body));
    return end(out.body);
  };
  next();
});

app.use(
  paymentMiddlewareFromConfig(
    { [`${method} ${routePath}`]: { accepts: { scheme: "exact", price, network: NETWORK, payTo } } },
    new HTTPFacilitatorClient({ url: FACILITATOR_URL }),
    [{ network: NETWORK, server: new ExactStellarScheme() }],
  ),
);
app[method.toLowerCase()](routePath, (_req, res) => res.json(RESOURCE));

app.listen(PORT, "127.0.0.1", () => {
  console.log(`seller ready on http://127.0.0.1:${PORT}${routePath} (${method}, price ${price}, ${NETWORK})`);
});
